{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Simotinib, a 4-anilinoquinazoline sharing the 3-chloro-4-fluoroanilino group, was reported to have good oral bioavailability after oral administration in NSCLC patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Gefitinib, which shares the same quinazoline core and 3-chloro-4-fluoroaniline, showed approximately 60% oral bioavailability in humans at 250 mg/day.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Zongertinib, a close piperidine-substituted analogue, was predicted to have 41% human oral bioavailability from multi-species pharmacokinetic profiling.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "BIBW 2992 (afatinib), another 4-anilinoquinazoline with the same aniline, showed good oral bioavailability in Phase I clinical pharmacokinetics.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "A structurally distant analogue had an estimated absolute oral bioavailability of only 3% in humans, providing the only affirmative low-F evidence; its low Morgan similarity limits transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Prediction is high: the query is a 4-anilinoquinazoline-type kinase inhibitor with the same 3-chloro-4-fluoroaniline and a basic N-methylpiperidine group. Multiple direct human/clinical analogues (gefitinib ~60%, zongertinib 41%, afatinib good, simotinib good) support F >= 20%. The only low absolute value (3%) comes from a structurally distant analogue and is outweighed.",
  "evidence_gaps": [
    "No absolute bioavailability study exists for the exact query molecule; most supportive values are relative, predicted, or from analogues rather than the query itself.",
    "Morgan similarities are modest (<0.36), so structural transfer is not exact.",
    "Some records do not specify absolute bioavailability with an IV comparator."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

